#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = path.join(ROOT, 'output');
const BLOCK = '**** YD001 SOURCE BLOCK ****';
const ENG = '**** ENGLISH ****';
const END = '**** END BLOCK ****';

function patchFile(rel, slug, T) {
  const fp = path.join(OUT, rel);
  const s = fs.readFileSync(fp, 'utf8');
  const applied = new Set();
  const parts = s.split(BLOCK);
  const out = parts.map((block, i) => {
    if (i === 0) return block;
    const slugM = block.match(/^\s*slug: (.+)$/m);
    const seifM = block.match(/^\s*seif: (.+)$/m);
    const markerM = block.match(/^\s*marker: (.+)$/m);
    if (!slugM || slugM[1].trim() !== slug) return BLOCK + block;
    const seif = seifM[1].trim();
    const marker = markerM ? markerM[1].trim() : 'main';
    const key = `${seif}#${marker}`;
    if (!(key in T)) return BLOCK + block;
    const enStart = block.indexOf(ENG);
    const enEnd = block.indexOf(END);
    if (enStart < 0 || enEnd < 0) throw new Error(`ENGLISH/END missing: ${rel} ${key}`);
    const before = block.slice(0, enStart + ENG.length + 1);
    const after = block.slice(enEnd);
    const text = T[key].endsWith('\n') ? T[key] : T[key] + '\n';
    applied.add(key);
    return BLOCK + before + text + after;
  });
  const missing = Object.keys(T).filter((k) => !applied.has(k));
  if (missing.length) throw new Error(`Keys not found in ${rel}: ${missing.join(', ')}`);
  fs.writeFileSync(fp, out.join(''), 'utf8');
  console.log(`OK ${rel} (${applied.size} blocks)`);
}

// --- mechaber (12) ---
patchFile('siman_016/mechaber/part-001.txt', 'mechaber', {
  '1#main': `The law of oto v'et beno (it and its offspring). In it are 12 seifim. It is forbidden to slaughter oto v'et beno in one day—whether the mother and afterward the son, whether the daughter, whether the son or daughter and afterward the mother.`,
  '2#main': `The prohibition of oto v'et beno applies with females—for that one is certainly its offspring; and if it is known with certainty that this is its father, they are not slaughtered in one day; and if he slaughtered, he does not receive lashes—for the matter is doubtful whether it applies with males or not.`,
  '3#main': `If he transgressed and slaughtered oto v'et beno in one day—they are permitted to eat them; and there are those who forbid {Rama: on that day to eat the last one slaughtered}.`,
  '4#main': `The "one day" stated in oto v'et beno—the day follows the night. How so? If he slaughtered the first at the beginning of the night of the fourth day, he may not slaughter the second until the beginning of the night of the fifth day; and if he slaughtered the first at the end of the fourth day before bein hashemashos (twilight), he may slaughter the second at the beginning of the night of the fifth day; and if he slaughtered the first at bein hashemashos of the night of the fifth day, he may not slaughter the second until the night of the sixth day; and if he slaughtered on the fifth day, he does not receive lashes.`,
  '5#main': `If it is attached after her (karukh aḥareha), the presumption is that she is its mother {Rama: but from doubt one is not concerned} (Tur).`,
  '6#main': `One who buys an animal is not concerned lest its mother or offspring was slaughtered that day; but the seller must warn the buyer and inform him whether he slaughtered the mother or offspring that day, or if he sold her to another to slaughter her that day; and if it is one of the four seasons when anyone who buys an animal usually slaughters it immediately—and they are: erev Pesach, erev Shavuot, erev Rosh Hashanah, and erev the last Yom Tov of the festival—he must inform him that he sold today the mother or daughter; and if he did not inform him, he slaughters and is not concerned, whether he bought from a Jew or from a non-Jew; and if it became known to him afterward that its mother or daughter was slaughtered that day, it is a mistaken transaction; and specifically when he sold both in one day; but if he sold the mother or daughter on the day before, he need not inform him; and if he sold one to the groom and the other to the bride, even if he sold on two days, he must inform him that certainly both are slaughtered in one day; if two bought oto v'et beno in one day, the first buyer slaughters and not the second {Rama: in what case is this said—when both bought from one person, for as soon as he sold to the first he could not slaughter what remained in his hand because the buyer took it on condition to slaughter it immediately (and therefore also the buyer from him may not slaughter, for he cannot sell him only the right in his hand) (Tur) (Be'er HaGolah)}; but if they bought from two people, both are equal and whoever slaughters first is alert and successful.`,
  '7#main': `The prohibition of oto v'et beno is only with a pure behemah, as it says "And an ox or sheep, it and its son you shall not slaughter in one day"; and it applies to a hybrid from species of sheep and species of goat.`,
  '8#main': `A deer that came upon a goat and gave birth—and he slaughtered the goat and its son—he receives lashes; but a goat that came upon a doe—they are forbidden to slaughter her and her son; and if he slaughtered, he does not receive lashes; if that daughter of the doe was female and gave birth to a son, and he slaughtered the female daughter of the doe and her son—he receives lashes.`,
  '9#main': `The prohibition of oto v'et beno is only through shechitah, as it says "you shall not slaughter"; but if he pierced (nichur—the meaning of nichur is inserting the knife in its nostrils and cutting) the first, or it became neveilah in his hand, it is permitted to slaughter the second; therefore a deaf-mute, imbecile, or minor who slaughtered the first among themselves—it is permitted to slaughter the second after them, for most of their acts are defective: {Rama: And if others see that they slaughter properly, it is forbidden to slaughter after them (Tur); so it appears to me.}`,
  '10#main': `It is permitted to slaughter the pregnant animal—the fetus is its mother's thigh; and if the fetus went out alive after its mother's shechitah and spread on the ground, they do not slaughter it in one day; and if he slaughtered, he does not receive lashes.`,
  '11#main': `A non-Jew who sold two animals and afterward said incidentally that they are oto v'et beno—he is not believed in what he said after he sold them and they left his possession; however, if he is believed to him, it is forbidden.`,
  '12#main': `An animal whose mother or daughter was slaughtered that day and became mixed with others and one must slaughter from them that day—how is it remedied? Pen them so they move from their established place, and take from them one by one and slaughter, for whatever is separated from the majority is separated; and the two remaining—it is forbidden to slaughter them that day. (Sharet Yehudah)`,
});

// --- siftei-kohen (26) ---
patchFile('siman_016/siftei-kohen/part-001.txt', 'siftei-kohen', {
  '1#_': `<b>Whether the mother and afterward the son or daughter, whether the son or daughter and afterward the mother.</b> And in these cases there is also lashes if it is known she is its mother—for it is plain to us we are concerned for the mother's seed.`,
  '2#_': `<b>For the matter is doubtful, etc.</b> See s.k. 17.`,
  '3#_': `<b>To eat the last one.</b> But the first in any case is permitted—for at the time they slaughtered it no prohibition was created at all; and the reason the last is forbidden—the Ran wrote is because of a penalty (as explained in Orach Chaim siman 318 regarding Shabbat); and it appears specifically we penalize him, but for others it is permitted; and so appears Perishah's view, and so appears the language of Beit HaGadol that the Rosh brought: one who slaughters oto v'et beno may not eat the last on that day—end of his words; and so appears from the proof the Rosh brought for this law from Rav Yosef—see there.`,
  '4#_': `<b>He does not receive lashes.</b> For perhaps at bein hashemashos it is still the fourth day.`,
  '5#א': `<b>If it is attached after her, presumption she is its mother.</b> Meaning: for the prohibition; but for lashes, attachment does not help until we know with certainty she is its mother; and so Maharshal chapter Oto V'et Beno siman 8; and so explicitly in the Talmud in Bekhorot (daf 24a): even attached after her and nursing from her—it is forbidden and he does not receive lashes; and this is what he wrote in seif 2 "the prohibition of oto v'et beno applies with females—for that one is certainly its offspring"—meaning for lashes, as appears there; and see above siman 15.`,
  '5#ב': `<b>But from doubt one is not concerned.</b> Even for the prohibition—even if it greatly resembles the mother in appearance or in other bodily signs—so too Maharshal there.`,
  '6#א': `<b>He is not concerned lest its mother or offspring was slaughtered that day.</b> And he need not ask afterward—for there is much doubt: perhaps this one has no mother; and even if you say it has a mother, perhaps he did not buy it for shechitah; and even if for shechitah, perhaps from here and after several days. Ran.`,
  '6#ב': `<b>But the seller must warn the buyer.</b> Even on other days that are not the four seasons if he slaughtered, etc.`,
  '6#ג': `<b>Or if he sold her to another to slaughter her that day.</b> Meaning: that he knows with certainty another will slaughter her that day—then he must inform so he not stumble through him; but it is not a mistaken transaction if he did not inform, for he can tell him slaughter tomorrow; but if he does not know with certainty another will slaughter her that day, he need not inform—even regarding prohibition, for perhaps also one who bought her will not slaughter her that day since it is not one of the four seasons.`,
  '6#ד': `<b>And if it is one of the four seasons, etc., he must inform that he sold today, etc.</b> Even though he does not know another will slaughter—for presumptively in these four seasons everyone buys for shechitah; and see Choshen Mishpat siman 199 seif 13.`,
  '6#ה': `<b>And erev the last Yom Tov of the festival.</b> For it is a festival by itself; and erev the first—the people are busy with sukkah and lulav and have no leisure for so much shechitah. Tosafot.`,
  '6#ו': `<b>He need not inform him.</b> Meaning: neither for prohibition nor mistaken transaction—for it is possible he will slaughter them before these four seasons—and requires study.`,
  '6#ז': `<b>He must inform him.</b> And it is also a mistaken transaction if he did not inform; and in our time, since the main shechitah for Yom Tov need is before Yom Tov, and likewise groom and bride slaughter a day or two before—he need not inform in a sale over two days; and so appears in Terumat HaDeshen; so too Bach.`,
  '6#ח': `<b>And whoever slaughters first, etc.</b> In the Talmud it is proved that even when they bought from one person, if the second preceded and slaughtered—he is alert and successful; therefore Bach was troubled and wrote: what the Tur wrote "and whoever slaughters, etc." is a matter on its own and refers above to when they bought from one person; and he strained unnecessarily, for in the Talmud it only says that if the second preceded he is alert and successful, but l'chatchila it is not proper to do so; and the Tur teaches us that when they bought from two people, whoever slaughters is alert and successful.`,
  '8#א': `<b>And he slaughtered the goat and its son—he receives lashes.</b> For it is plain we are concerned for the mother's seed; and here there is partial sheep, and we expound in the Talmud "sheep" even partial sheep.`,
  '8#ב': `<b>But the goat that came upon the doe, etc.</b> And Maharshal there siman 5 ruled like Rashba and Tur that it is permitted to slaughter the doe and her son even l'chatchila, as we say in the Talmud "sheep and its son the Merciful One said," and not "deer and its son"; and I do not know what Beit Yosef wrote in name of R' Yosef ibn Chaviv that Rambam's view forbids l'chatchila because of marit ayin—for what marit ayin applies when everyone knows it came from the goat; and if we say the viewer will be concerned for this—even regarding a regular son of a doe; and further, we do not find anywhere such marit ayin.`,
  '8#ג': `<b>If that daughter of the doe, etc.</b> Atzat HaZahav and Bach challenged: here Rambam and Mechaber hold we are certainly concerned for the father's seed—otherwise he would not receive lashes from doubt; and above in seif 2 they wrote "if known this is certainly its father they are not slaughtered in one day, and if he slaughtered he does not receive lashes—for the matter is doubtful whether it applies with males"; and they answered: there specifically they doubt whether oto v'et beno applies also with father because we expound "its son attached after it" to exclude the father whose son is not attached after it; but here it is plain we are concerned where the goat came upon the doe and she bore a female—for since this female has partial sheep it is considered as if entirely sheep; and if this female bore daughter or son and he slaughtered the female and her offspring—he receives lashes perforce; and it is astonishing one cannot distinguish thus as plain in the Talmud beginning chapter Oto V'et Beno (beginning daf 79) regarding that which Shmuel followed his reasoning there (and further, whence to doubt this exposition—and examine); and further it is astonishing—in Beit Yosef siman 13 he wrote Rambam's view is we doubt whether we are concerned for father's seed or not, and so Kessef Mishneh chapter 12 of Laws of Shechitah law 11; and further in chapter 13 law 4 Rambam wrote one born from behemah and chayah must cover blood and does not bless, and Mechaber below siman 28 seif 2—and if we hold certainly concerned for father's seed, why not bless; and in Perishah and Bach siman 28 they intended one matter to answer this because specifically regarding sheep we say "sheep" even partial sheep, but regarding chayah we doubt perhaps it requires complete chayah and does not count at all per sugya chapter Oto V'et Beno (daf 79b) that proves there explicitly that where we say sheep even partial sheep, likewise deer even partial deer—see there; and further it is astonishing—for Rambam chapter 9 of Laws of Bekhorim wrote: deer that came on goat and bore—offspring liable for half gifts, as "if sheep even partial sheep"; goat that came on doe—offspring exempt from gifts—end; and so Mechaber below siman 61 seif 8—apparently we doubt; and therefore one can say bring proof we are concerned and I will give you half; as we say in the Talmud; and further in chapter 9 of Laws of Kilayim law 6 Rambam wrote those born from donkey are forbidden with those born from horse, and so Mechaber below siman 297 seif 9—and this is because we doubt; if certainly concerned they are permitted as stated explicitly in Talmud beginning Oto V'et Beno—and requires study; and it is astonishing on what Maharshal wrote chapter Oto V'et Beno siman 2 that the halachah follows Chanania that oto v'et beno applies with father and son, and immediately after in siman 3 ruled regarding oto v'et beno we are not concerned for father's seed and permitted to slaughter father with son in one day—and requires study. And know there is practical difference even for us in what they slaughter—for then he is disqualified for testimony from the Torah, as we hold in Choshen Mishpat siman 34; and likewise regarding kiddushin of a woman with a non-Jew siman 42—see there.`,
  '9#א': `<b>Only through shechitah.</b> And included: if he slaughtered and it was found treifah—they receive lashes if he slaughters the second—for it did not become neveilah through shechitah; and so in the Talmud and poskim.`,
  '9#ב': `<b>Or it became neveilah, etc.</b> Bach wrote: however if it became neveilah in his hand through one of the matters we are stringent about, such as shehiyah in minority of the latter simanim, and the like in rabbinic disputes—one may not slaughter the son or mother after it; it appears to me perforce; and so Semag siman 167: if there was shehiyah or chaladah in minority of simanim, or combination of shehiyah, or a defective knife was found after slaughter—they forbade them from doubt; and likewise all such cases it appears forbidden to slaughter the second, and if he slaughtered he does not receive lashes perforce.`,
  '9#ג': `<b>Therefore deaf-mute, etc.</b> Bach wrote: it appears the same when the mother was slaughtered—it is permitted to give the son to deaf-mute to slaughter among themselves; and a fortiori permitted to sell to non-Jews even though the non-Jew will pierce it that day—end; and requires study—for regarding deaf-mute, though there is no oto v'et beno, nevertheless it is forbidden to give them to slaughter among themselves, even to throw to dogs, as above siman 1 seif 5—see there.`,
  '9#ד': `<b>Among themselves, etc.</b> But when others oversee them—the Mechaber's view is their shechitah is valid even if not expert and does not know how to train his hands, as I wrote in siman 1 s.k. 25; and even though I wrote there to forbid, nevertheless here one should be stringent in a d'oraisa prohibition—and examine; and see above siman 28 s.k. 23.`,
  '10#_': `<b>They do not slaughter.</b> Since because of marit ayin it requires shechitah when it spread on the ground; and he does not receive lashes since from the Torah it does not require shechitah and is permitted through its mother's shechitah, as above siman 13; and see what I wrote in s.k. 3 and seif 14.`,
  '11#א': `<b>He is not believed.</b> For a non-Jew is not believed in any testimony, as below siman 127 s.k. 19; and Atzat HaZahav wrote the reason: to enhance his sale he says so; and he did not aim well—for here enhancing his sale does not apply at all; if it applied he would not be believed even before he sold them; rather for this he is believed before he sold them through migo that if he wished he would not sell them or would cheapen them; but where enhancing his sale applies, even if he has migo he is not believed—as explained in responsum of Rashba siman 118, source of this law; however from words of Rosh and Mordechai and Hagahot Maimoniyot I brought in siman 127 there it is explained: where it is in his possession he is believed even where one could say he says so to enhance his sale—and see there.`,
  '11#ב': `<b>If he is believed to him—it is forbidden.</b> Even if not speaking incidentally—so in responsum of Rashba there; and see these laws in siman 127 s.k. 14.`,
  '12#א': `<b>Pen them so they move from their established place.</b> For as long as they are together as live animals they are not nullified even in a thousand, as below siman 110.`,
  '12#ב': `<b>Forbidden to slaughter them that day.</b> For it is half-and-half; and see above siman 110 seif 6 where this is explained at length, with Heaven's help.`,
});

// --- turei-zahav (16) ---
patchFile('siman_016/turei-zahav/part-001.txt', 'turei-zahav', {
  '1#_': `<b>Whether the mother.</b> In the Gemara they say: oto v'et beno—I have only it and its son; whence do I include its son and it? It says "you shall not slaughter"—behold two. Rashi: he warned both, whether he slaughtered the mother or the daughter; and you do not find two performing one transgression except with three animals. How so? Daughter, mother, and daughter—for if mother and two sons, why do I need a verse—it is obvious; whether one or two, as this one is liable so that one is liable; and if cow and its daughter and daughter's daughter—it is obvious both are oto v'et beno; rather necessarily one slaughters the cow and the two slaughter mother and the third daughter—and it teaches us that for its son and it one is also liable—that is the second.`,
  '2#_': `<b>Doubt whether it applies with males.</b> For we doubt in the Gemara whether we hold like Chanania who holds we are concerned for father's seed, and we hold concerned stringently but not for lashes—for one does not receive lashes on doubt.`,
  '3#_': `<b>Permitted to eat them, etc.</b> In the Gemara they say: even though it is written "you shall not eat any abomination," and we expound "anything I made abominable to you"—here it is different, for since the Merciful One forbade it lacking time for the Most High—that is, before the eighth day—from this it is permitted to an ordinary person here lacking time; and one view is in Beit HaGadol: he holds to forbid in any case on that day because of penalty for doing a transgression similar to cooking on Shabbat—and the Gemara did not exclude except that it is not forbidden forever from force of "any abomination."`,
  '4#_': `<b>The day follows the night.</b> As in Bereishit—to exclude korban where the night follows the preceding day; and in the Gemara a reason is given for this.`,
  '5#_': `<b>Attached after her.</b> Meaning: constantly clinging, following her—we say presumptively she bore and nursed it; therefore attached after her.`,
  '6#א': `<b>And if it is one of the seasons, etc.</b> According to this reading: it is one of these seasons that the seller must warn even without specification if the first buyer did not inform explicitly he wants to slaughter today. In Tur it is written "if it is one of," without vav—automatically also in one of these seasons he need not warn unless the first buyer said explicitly he wants to slaughter today; and this is astonishing—for then why "one of the seasons"; and I saw they enter with strain for this; and to me it appears what the Tur wrote "or sold her to another to slaughter today" means: today he sold her for slaughter—that is, to exclude if he sold for plowing; it turns out he sold to him without specification for slaughter; nevertheless since the sale was made today he will certainly slaughter her today if it is one of the seasons—it turns out for the law everything goes in the buyer's possession; therefore it appears correct.`,
  '6#ב': `<b>And erev the last Yom Tov.</b> Because it counts as a festival by itself and was dear to them and they increase joy; and on the first Yom Tov they are busy with sukkah and lulav mitzvot; and erev Yom Kippur they were accustomed to fowl and fish.`,
  '6#ג': `<b>Only the right in his hand.</b> Ostensibly one could learn from this: if one swore not to slaughter his animal but only keep it for plowing and sold it—even the buyer cannot slaughter, for the seller had no right to slaughter and can sell only the right in his hand; and this is not so at all—for then it would be difficult from here on one who swore not to sell something and transgressed and sold, for we say in Choshen Mishpat siman 208 it is a sale and not as Rama wrote in Yoreh Deah siman 230; and I wrote from this also below siman 228 seif 35. Rather it appears they did not say here he cannot sell only his right, but not to annul another's right in what he already acquired; but if there is no annulling another's right, the buyer has no obligation to fulfill the seller's oath—for as long as it was in his possession the oath applied, not when it came to another; and even though a person can forbid his own thing upon another—even when it leaves his possession, as Tur Yoreh Deah siman 217—there it is different, for the prohibition applies to the object and remains on it forever, unlike an oath that applies to the person who swore, as explained in Laws of Vows—therefore there is no obligation except while in his possession; but on the object nothing applies, as explained.`,
  '6#ד': `<b>Alert and successful.</b> Rashi explains: alert—for he did not do a prohibition; successful—that he will eat meat; and it appears to me since the Sages praised and called him alert, it implies there is virtue in one who preceded and slaughtered—that is, he cannot come to prohibition, unlike the second who might forget and do a prohibition and slaughter; therefore the court should not involve itself and say they should cast lots who slaughters first—for they have no right to annul each one's right to be called alert—that is, whoever each may slaughter; unlike when they bought from one and the second preceded and slaughtered before the first buyer—for he is not called alert but even a sinner is called so, for he stole the first buyer's right—as explained clearly.`,
  '8#א': `<b>The goat and its son—he receives lashes.</b> For "sheep and its son the Merciful One said" implies its son even any that is not sheep; and Tur wrote: deer that came on he-goat and bore daughter, and that daughter bore daughter, and he slaughtered her daughter and daughter's daughter—liable; and the reason: we hold like the Rabbis who dispute R' Eliezer and hold the Torah said "sheep" even partial sheep—nevertheless lashes because the daughter is partial sheep through its mother, for we follow the mother.`,
  '8#ב': `<b>Forbidden to slaughter her and her son.</b> Rashba and Tur disagreed and permitted even l'chatchila; and it appears to me Shulchan Aruch's reason per Rambam: Rav Chisda said all agree regarding that doe and her son he-goat is exempt—implies forbidden; and so in all exemptions of Shabbat except three and similar, Beit Yosef brought in siman 87 regarding milk; and it is possible there is a rabbinic prohibition since it teaches exempt and does not teach permitted—end; and the reason here: lest it be confused with doe and her son.`,
  '8#ג': `<b>That daughter of the doe, etc. And her son—he receives lashes.</b> Many wondered on this—for the conclusion in the Gemara is we doubt whether we are concerned for father's seed, as I mentioned in seif 2—why lashes here, lest we are not concerned for father's seed and the female has no father's seed at all and is not even partial sheep, and one cannot emend "he does not receive lashes"—Rambam concludes afterward likewise kilayim from goat and sheep—lashes; and on this matter there is room for further study in Rambam that Beit Yosef brought siman 297 in Laws of Kilayim that Rosh wondered on Rambam who ruled also lashes because concerned for father's seed, and Beit Yosef labored to find a way to emend his words.`,
  '9#_': `<b>Therefore deaf-mute, etc.</b> It appears the same with an adult who does not know laws of shechitah; and that the mishnah mentions deaf-mute—even knowing ones, as siman 1—for it is plain even an adult who does not know, most of his acts are defective; and they said in first chapter of Chullin (daf 9) regarding adult who does not know: sometimes he was delayed and pressed and did not know—sometimes implies there is doubt and it is not plain; this "sometimes" refers to "and did not know," but delay or pressing are plain; and so proved from that which they said afterward "and if others see, etc., forbidden"—this is not so great a novelty, for here b'dieved shechitah is permitted; he should have stated the novelty: even adult who does not know, his shechitah is forbidden b'dieved if he slaughtered alone—for nevertheless forbidden to slaughter after him; rather certainly permitted; but since poskim did not mention this explicitly, I have no authority to permit oto v'et beno after shechitah of adult who does not know; nevertheless it appears clear if he transgressed and slaughtered after him there is no eating prohibition, even for those who forbid in seif 3; and further it appears plain: when the first animal slaughtered became forbidden from some doubt of treifot in shechitah—one should not be lenient because of that to slaughter its son that day; and regarding other treifot it is plain forbidden to slaughter after it—for it is disputed in the Gemara (daf 81) and halachah follows Rabbis who forbid, for shechitah that is not valid—its name is shechitah.`,
  '10#_': `<b>He does not receive lashes.</b> For from the Torah it does not require shechitah.`,
  '11#_': `<b>After he sold them, etc.</b> Implies if he said so at time of sale he is believed to forbid; and so from what Rosh wrote in chapter Oto V'et Beno: I saw written in name of Rav Achai: if a non-Jew merchant sells animals one must be concerned lest he sold the mother today; and it is not reasonable it is common, and we do not establish prohibition so long as the seller did not inform, etc.; if there is concern from doubt, etc.—end; implies if he informed at time of sale one must forbid slaughtering that day the animal bought from him; and it is plain if there is reason he does so to enhance his sale, his words are nothing, like that in last chapter of Yevamot (daf 122): non-Jew who sells produce and said they are orlah—his words are nothing; and see siman 122 seif 6 more on law of idolatry in this.`,
  '12#_': `<b>Pen them so they move.</b> Meaning: strike them and drive them from fixed place; then we follow majority; and what to analyze here I wrote siman 10 seif 4.`,
});

// --- baer-heitev (19) ---
patchFile('siman_016/baer-heitev/part-001.txt', 'baer-heitev', {
  '3#_': `<b>To eat the last.</b> But the first is permitted—for at slaughter no prohibition was created; and Shach wrote it is because of penalty, specifically for him but for others permitted.`,
  '5#_': `<b>Concerned.</b> Meaning for prohibition; but for lashes not until known with certainty she is its mother; and Maharshal wrote: even if similar in mother's appearance or other bodily signs—even so not concerned.`,
  '6#א': `<b>That day.</b> And Shach wrote: need not ask afterward—for much doubt: perhaps no mother; and even if it has a mother, perhaps not bought for shechitah; and even if for shechitah, perhaps from here and after several days.`,
  '6#ב': `<b>That day.</b> Shach's explanation: that he knows with certainty.`,
  '6#ג': `<b>Of the festival.</b> And Shach wrote: but not erev the first Yom Tov of the festival—for then people are busy with sukkah and lulav and have no leisure for so much shechitah.`,
  '6#ד': `<b>To inform him.</b> Meaning: neither for prohibition nor mistaken transaction—for possible he will slaughter them before these four seasons.`,
  '6#ה': `<b>One day.</b> And Shach wrote: it is also mistaken transaction if he did not inform; and in our time main shechitah for Yom Tov is before Yom Tov; and groom and bride slaughter a day or two before—need not inform in sale over two days; so Bach ruled.`,
  '6#ו': `<b>Right in his hand.</b> And Taz wrote: we do not learn from this if one swore not to slaughter his animal but keep for plowing and sold—even buyer cannot slaughter; this is not so—for we hold in Choshen Mishpat siman 208 if he swore not to sell and sold, it is a sale, not as Rama wrote in Yoreh Deah siman 230; rather here it deals with annulling another's right the first already acquired; but on the object nothing applies even though his he may forbid upon another when it leaves his possession—see below siman 217 seif 8: prohibition applies to object, unlike oath on person who swore.`,
  '6#ז': `<b>And successful.</b> And Taz wrote: if they bought from one and second preceded and slaughtered—not called alert and successful; but l'chatchila forbidden to do so; and even a sinner is called so—for he stole first buyer's right; and this is Gemara Chullin daf 84—and requires study; and see Knesset HaGedolah and Shach.`,
  '8#_': `<b>He receives lashes.</b> Taz and Shach wondered on this law and wrote: did we not say in the Gemara we doubt whether concerned for father's seed—why lashes here, lest not concerned and this female had no father's seed at all and was entirely deer; requires study; and practical difference even for us in what they slaughter—for then disqualified for testimony from Torah, as we hold Choshen Mishpat siman 34; and likewise kiddushin of woman with non-Jew siman 42; and in my responsum I wrote on the margin a correct answer: specifically regarding this law Rambam holds thus because of scriptural decree.`,
  '9#א': `<b>You shall not slaughter.</b> And Shach wrote: likewise if he slaughtered and it was found treifah—for it did not become neveilah through shechitah.`,
  '9#ב': `<b>The second.</b> And Shach wrote: however if it became neveilah through one of matters we are stringent about, such as shehiyah in minority of latter simanim—it appears forbidden to slaughter; and if he slaughtered he does not receive lashes—Semag, Bach, Shach.`,
  '9#ג': `<b>Defective.</b> And Taz wrote: regarding adult who does not know laws of shechitah we have no authority to be lenient, since not found explicitly; and Shach wrote: to non-Jew permitted l'chatchila to sell that day even though he knows non-Jew will pierce today; but deaf-mute, imbecile, minor—forbidden to give them to slaughter among themselves even to throw to dogs, as above siman 1 seif 5.`,
  '9#ד': `<b>As stated.</b> And Shach wrote: even if not expert and does not know how to train hands, as I wrote siman 1; and even though I wrote there to forbid, nevertheless here one should be stringent in d'oraisa prohibition.`,
  '10#_': `<b>He does not receive lashes.</b> Reason in Shach: from Torah no shechitah required, only rabbinically; therefore no lashes; and see seif 13.`,
  '11#א': `<b>His possession.</b> And Taz wrote: but as long as he did not sell, he is believed—for enhancing his sale does not apply here he said so; however from words of several poskim it appears: as long as in his possession he is believed even where one could say enhancing his sale.`,
  '11#ב': `<b>Forbidden.</b> And Shach wrote: even if not speaking incidentally; and see below siman 127; and if at time of sale he said so—believed; and if it appears he does so to enhance his sale—nothing; and see siman 127 where in his possession he is believed nevertheless.`,
  '12#א': `<b>Their established place.</b> For as long as together as live animals not nullified even in thousand, as below siman 110.`,
  '12#ב': `<b>That day.</b> Because it is half-and-half.`,
});

// --- beer-hagolah (25) ---
patchFile('siman_016/beer-hagolah/part-001.txt', 'beer-hagolah', {
  '1#_': `Mishnah Chullin daf 82; and he derived it from verses in the baraita there.`,
  '2#_': `Dispute of tannaim there daf 79; and Rosh brought halachah follows Chanania who is concerned for father's seed; and so Rashba in Terumat HaDeshen; and so Razah and Rabbenu Tam; and so Rambam chapter 12 of Laws of Shechitah law 11; and Beit HaGadol and She'iltot and Rif ruled Chanania does not exist.`,
  '3#א': `Tur in name of Rambam and meaning of mishnah.`,
  '3#ב': `There in name of Beit HaGadol from reason Rosh and Ran and Rabeinu Yerucham wrote.`,
  '4#א': `Mishnah there.`,
  '4#ב': `Rambam's language there end of chapter.`,
  '5#_': `Tur from meaning of Gemara there; and so Rashba wrote.`,
  '6#א': `Baraita there.`,
  '6#ב': `Mishnah there.`,
  '6#ג': `Mishnah there daf 83.`,
  '6#ד': `Rosh there; and so Rashba in his chiddushim.`,
  '6#ה': `Ramban; and to this agreed Rosh, Rashba, and Ran.`,
  '6#ו': `There in mishnah words of R' Yehudah; and per Rashi there.`,
  '6#ז': `Mishnah there daf 82.`,
  '6#ח': `Rosh there.`,
  '7#_': `Baraita there; and Rambam's language there law 8.`,
  '8#א': `Statement of Rav Chisda there 79 regarding "sheep the Merciful One said" and its son—all.`,
  '8#ב': `Rambam's language there chapter 12; and Tur brought it and wrote it appears permitted l'chatchila; and Rashba wondered on him in chiddushim and Terumat HaDeshen and concluded there: if sheep the Merciful One said—even deer lashes too; if sheep the Merciful One said and not deer—whence prohibition; and that which we say regarding he-goat that came on doe—for prohibition we must explain: he-goat that came on doe and bore daughter and daughter bore son, as we established at the beginning—end.`,
  '8#ג': `And so also in Rambam there law 9; and it is astonishing—for we hold like Rabbis who doubt whether concerned for father's seed, as Rambam wrote there law 11 and Beit Yosef brought above seif 2; and further Rambam wrote in chapter 9 of Laws of Kilayim similarly lashes; and Kessef Mishneh concluded there: better to read "he does not receive lashes."`,
  '9#א': `Mishnah there daf 81.`,
  '9#ב': `Mishnah there daf 86; and like R' Meir there in Gemara.`,
  '10#א': `Rambam there chapter 12 of Laws of Shechitah law 10 and all of it.`,
  '10#ב': `There from Tosefta there; and like Sages; and Beit Yosef in name of Avodat HaGershuni.`,
  '11#_': `Rashba in responsum siman 118.`,
  '12#_': `Rosh in his rulings there in name of Beit HaGadol.`,
});

// --- beur-hagra (18) ---
patchFile('siman_016/beur-hagra/part-001.txt', 'beur-hagra', {
  '1#א': `<b>Or the daughter.</b> There in sugya in several places.`,
  '1#ב': `<b>Whether the mother, etc.</b> There 82a mishnah and also.`,
  '2#א': `<b>(Seif 2) And if known, etc.</b> From doubt we are not concerned—therefore he stated there 83a "I sold the mother, etc." Rosh; and see there. <br><b>(Likut) And if known with certainty, etc.</b> Specifically such a case; and this is what he stated "I sold the mother" and no difficulty father; and so throughout the chapter because it is uncommon to be known. Rosh 82 (end).`,
  '2#ב': `<b>For the matter is doubtful, etc.</b> As written end of Ketubot halachah follows R' Yehudah in mules; and we say in Chullin there 79a we doubt; and so R' Eliezer and Rabbis there hold.`,
  '3#א': `<b>(Seif 3) If he transgressed, etc.</b> As written beginning of chapter "both are valid and the second valid"; and there 115a "oto v'et beno is not forbidden, etc."`,
  '3#ב': `<b>And there are those who forbid, etc.</b> From that which they say there 82a: tanna—if the first preceded, etc.—implies otherwise he did two prohibitions and may not eat in Israel; and what mishnah states "valid" is by Torah law, and even rabbinically after that day; but for that day forbidden like act of Shabbat; and as written 14a his shechitah is valid and they said in Gemara forbidden in eating that day; and so there 146a—also by Torah forever, as written there also on act of Shabbat; "but from now," etc.`,
  '4#_': `<b>(Seif 4) How so, etc.</b> Language of Tosefta there.`,
  '5#_': `<b>(Seif 5) (Likut) If it is attached, etc.</b> For prohibition it requires; and it was not resolved in Bekhorot 24a; and so Rashbag who entered, etc., males hanging, etc., they asked, etc.; and there R' Yochanan said see, etc., until will come, etc.; and so Rosh there it was not resolved (end).`,
  '6#א': `<b>(Seif 6) On the seller to warn, etc.</b> Tur; and his view: all year must warn; but in four seasons even if first sold without specification must inform; and also mistaken transaction; unlike other days of year one could say "I did not sell you for slaughter today."`,
  '6#ב': `<b>And if (he did) not inform, etc.</b> From that which it says must inform the seller and not the buyer—and more one must warn the one causing another to stumble; but certainly the buyer need not be concerned, for we do not establish prohibition; and it is double doubt if it has a mother and it exists and was sold, and today sold; and this is what he stated "whether bought from non-Jew"—otherwise one would have to forbid buying from non-Jew forever, even all year lest sold today for slaughter, and a non-Jew has no testimony.`,
  '6#ג': `<b>In what case, etc.</b> Per Rashi there s.v. for law, etc.`,
  '7#_': `<b>(Seif 7) There is no prohibition, etc.</b> There 79b; and in Torat Kohanim; and Rif and Rosh brought: ox and not chayah, sheep and not fowl.`,
  '8#_': `<b>(Seif 8) But the goat, etc.</b> All poskim already cried out on this; and sugya of Gemara is in second section: even l'chatchila permitted; and latter section forbidden and no lashes; and daughter of goat in first section with her son—lashes.`,
  '9#_': `<b>(Seif 9) And if others, etc.</b> Mishnah there.`,
  '10#_': `<b>(Seif 10) After, etc.</b> There 74a; and like Sages; and in Tosefta chapter 4: one who slaughters the animal and found in it nine-month live fetus, etc., and liable for oto v'et beno per R' Meir; and Sages say: not forbidden for oto v'et beno, as it says "it and its son you shall not slaughter"—that which requires shechitah is forbidden for oto v'et beno, and that which does not require shechitah is permitted for oto v'et beno.`,
  '11#א': `<b>(Seif 11) Non-Jew, etc.</b> For there is no testimony of non-Jew, as written chapter 4 of Yevamot (47a) "for your words you are a non-Jew," etc.; and what is written end of Yevamot: specifically to enhance his sale he is not believed—here he is believed because sale in his hand and believed through migo if he wished he would not sell or not sell cheaply; and this is what he stated "after he sold them," etc.`,
  '11#ב': `<b>And if believed to him, etc.</b> As written regarding single witness chapter 3 of Kiddushin (66a): even though not believed, if you believe him, etc.; and likewise anyone not believed.`,
  '12#_': `<b>(Seif 12) Animal, etc.</b> Per Rabbenu Tam in Tosafot there 95a s.v. here too, that he distinguishes between kodashim and idolatry and other prohibitions—for in other prohibitions even l'chatchila permitted; and Rosh there; and see siman 110 seif 6 in hagahah "two" in one answer; and Peri Chadash there.`,
});

// --- kereti (16) ---
patchFile('siman_016/kereti/part-001.txt', 'kereti', {
  '2#א': `For the matter is doubtful—he wrote "it" and we expound to include father's seed; and Sages hold to distinguish; and Chanania holds to distinguish—no verse needed; and tannaim did not decide this until R' Eliezer and Sages—both doubt this.`,
  '2#ב': `Doubt—see Peleti what I wrote whether permitted to slaughter at bein hashemashos—for double doubt; and in which bein hashemashos is the matter doubtful.`,
  '3#_': `To eat the last—penalty like cooking on Shabbat; and Shach's view: they penalized only the slaughterer, not others; and see Peleti one should be stringent even if slaughterer acted b'shogeg—see there.`,
  '4#_': `And if he slaughtered at bein hashemashos first on fourth day—whether permitted to slaughter second at bein hashemashos beginning fifth day; and per Tosafot chapter 2 of Shabbat daf 34b—permitted in any case: if this bein hashemashos is day, also second is day, or both night—and then in any case there is no one day; but per Rashi there and Rambam chapter 1 of Laws of Offerings—it could be one day and one night, and therefore forbidden.`,
  '5#_': `Attached, etc.—stringently we say so; but there are no lashes until clarified it is her offspring.`,
  '6#א': `On seller to warn buyer—all year obligated to warn, for they are certainly slaughtered; and if he did not inform—mistaken transaction, for he can claim slaughter tomorrow; and so Shach.`,
  '6#ב': `Erev Pesach—not first day of festival, because they are busy eating in sukkah, etc. Tosafot.`,
  '6#ג': `In what case, etc.—Peri Chadash elaborated: if purchase was on one day mother and son only two days before Yom Tov—whether must inform; and since among us this does not apply, I did not copy his words to debate; and Peri Chadash wrote: if known they slaughter on one day in our time—must inform; and this is plain.`,
  '8#א': `Deer on goat—even though Gemara in Bekhorot implies behemah does not give birth—it is possible majority and all Chazal spoke is majority but minority conceives; and from this they spoke here. (And with this many difficulties are resolved.)`,
  '8#ב': `And its son—lashes—Peri Chadash wrote: certainly concerned for seed if sheep even partial sheep; and this is unnecessary—for mother is goat, what difference in its son—son is called even any; and need not be sheep even partial sheep.`,
  '8#ג': `And if he slaughtered—he does not receive lashes—this is Rambam's view: even though sheep the Merciful One said and not deer—nevertheless there is no Torah prohibition, but rabbinically forbidden; and Rambam supports from Rav Chisda: exempt and did not say permitted—learn exempt but forbidden; and Rashba and other poskim disagree and hold permitted l'chatchila; and it appears they depend on what afterward Rambam holds: therefore they forbade doe and her son—decree lest they slaughter her son and son's son and there be lashes as I wrote to him; but they hold even if slaughter son and son's son—no lashes; how decree when mistake has no clear prohibition—and requires study.`,
  '8#ד': `Lashes—many authors wondered; and see Peleti where I labored greatly to settle Rambam's words: even though he holds we doubt whether concerned for father's seed, as explained this siman seif 2—if so he-goat on doe, if not concerned for father's seed, this is entirely deer; nevertheless he holds from tradition "sheep even partial sheep"—that even if concerned for father's seed, partial seed and father's power is mixed in it—for otherwise how find kilayim forbidden in kodashim; and also if mother treifah and male kosher—offspring kosher, for zeh v'zeh gorem—learn there is father's power and it is partial sheep; therefore tradition "sheep even partial sheep" and liable for lashes; and see there what I wrote not to challenge from Gemara; and other poskim do not hold this reasoning per plain Gemara—no lashes at all, only doubt of prohibition perhaps concerned for father's seed and "sheep even partial sheep"; and much practical difference: one—if doubt in slaughter whether mother was slaughtered or only pierced, one could say offspring permitted from double doubt first that piercing suffices; and if you say shechitah—lest second is not behemah but chayah; and so many differences; and if deer on goat and bore daughter—that daughter with her son—all agree slaughterer liable for lashes, concerned for seed if certain and sheep even partial sheep—and plain.`,
  '9#_': `Or neveilah—meaning certainly; but doubt of neveilah in shechitah; and likewise in matters we are stringent such as shehiyah in minority of latter simanim—plain forbidden to slaughter second that day and no lashes.`,
  '10#_': `And if he slaughtered—he does not receive lashes; and if he slaughtered and mother found treifah and he slaughtered her son—it appears full prohibition, since mother's shechitah helps and four simanim kosher the Merciful One—behold complete shechitah; and from Torah to be lenient—and it is d'oraisa forbidden.`,
  '11#_': `After he sold them—but before selling plain one must be concerned for his words through migo he could kill them and the like; and it appears nevertheless no lashes obligation; practical difference—to disqualify testimony: though non-Jew believed to forbid since in his possession, but to obligate lashes—not believed.`,
  '12#_': `Animal, etc.—source of these matters see below siman 110 at length.`,
});

// --- peleti (3) ---
patchFile('siman_016/peleti/part-001.txt', 'peleti', {
  '2#_': `This is doubtful—we doubt whether concerned for father's seed; and there is doubt whether permitted to slaughter the father at bein hashemashos—and this too is doubtful, as written in seif 4; and if so it is double doubt: doubt we are not concerned for father's seed; and if you say we are concerned, lest yesterday or tomorrow is the day; and see Ran Sukkah—it appears at bein hashemashos at edges of day it is not doubtful, for we depend it is day—and the matter requires study and is not its place; and I elaborated in Magen Avraham.`,
  '3#_': `On that day to eat the last—if b'shogeg permitted or forbidden—not resolved; and view of many authors: even on Shabbat rule like R' Meir that b'shogeg permitted; and so here all could agree; however from proof Rosh brought for this case—that we say if first preceded and slaughtered, alert for he did mitzvah and successful that he ate meat—and Rosh inferred the fetus does not eat meat—from this implies b'shogeg also forbidden—for otherwise what relevance that first eats meat, for even second who transgressed b'shogeg eats since he did not act intentionally, all the more first where nothing was done; or b'shogeg also forbidden like Shabbat—and one should be stringent.`,
  '8#_': `If that daughter of the doe, etc.—the great Shach in s.k. 15 wrote many challenges on Rambam: one challenge—how obligate lashes, for he ruled we doubt among Sages whether concerned for father's seed, as explained above seif 2 doubtful whether applies with males—if so if doubtful how lashes; and Shach rejects all poskim on this; and the main challenge: Gemara is arranged daf 80—Rav Pappa said in oto v'et beno: he-goat on doe—for prohibition Rabbis hold forbidden and R' Eliezer permits; deer on he-goat—for lashes; and how did Rambam write against Gemara; and further regarding gifts he ruled deer on he-goat liable half gifts from doubt, and he-goat on doe exempt from gifts from doubt; and here he establishes certainly liable for lashes; and also regarding kisuy hadam Rambam wrote unconditionally both he-goat on doe and deer on he-goat cover and do not bless and do not slaughter on Yom Tov—and this indicates doubt; if certainly liable for lashes, bless and cover on Yom Tov—see there he elaborated and left requiring study: truly all his challenges require study and especially against arranged Gemara words—no lashes—and requires study. And since we must toil to settle our great rabbi's words who did not err in Gemara words and his own words—I toiled and found with God's mercy slight settlement for his words. And examiner in justice weighing my words in mind will find rest in plainness. And he is: Rambam explains Rav Chisda's statement "all agree regarding that doe and her son he-goat exempt—for sheep the Merciful One said," etc.; and he explains: since it says exempt and not permitted—learn he holds exempt but forbidden; and so ruled exempt but forbidden; and one may infer what Rav Chisda teaches exempt from lashes and states reason "sheep," etc.—behold he-goat itself is not called he-goat if not concerned for father's seed it is not he-goat at all; and if he slaughtered her and her son even from he-goat—no lashes, lest not he-goat at all; and if so from where lashes if he slaughtered her and the mother who is entirely doe—obligation of lashes comes from nowhere, for she and her daughter both not in category of behemah to obligate lashes; and from this supports Rambam: truly daughter and her daughter liable for lashes even though daughter born from he-goat on doe; but slaughtering her and her mother who is doe—exempt as Rav Chisda said. And further proof for Rambam: he holds as Tosafot there 79 s.v. what is, etc.—they challenged R' Eliezer why its milk forbidden; Tosafot: R' Yochanan holds R' Eliezer does not dispute in oto v'et beno except lashes but to forbid agrees we doubt whether deer partial deer—see there; therefore in baraita teaching unstam R' Eliezer says koy—oto v'et beno does not apply—perforce lashes do not apply but prohibition exists, as Tosafot state explicitly R' Eliezer disputes only lashes for we doubt whether we say deer even partial deer; and therefore Rabbis who dispute koy unstam dispute in all cases both he-goat on doe and deer on he-goat—for R' Eliezer in all forms forbids and no lashes; if so Rabbis who hold it applies in all forms deal specifically stating R' Eliezer in all forms—for R' Eliezer no difference both forbidden and no lashes, and Rabbis who dispute unstam dispute only in one form deer on he-goat, and in other form hold like R' Eliezer only prohibition—great strain on sugya and baraita language; therefore Rambam holds truly for Rabbis in all forms lashes and in all forms they dispute. And the reason is rejected: he holds as Tosafot themselves there s.v. agrees, etc.—R' Yochanan holds he-goat on doe; and even according to those not concerned for father's seed—nevertheless Rabbi expounded "ox" to obligate in gifts—see there; and must explain R' Yochanan's words: behold entirely chayah—how obligate chayah in gifts; and must say certainly father's behemah power is in it—compare kosher that came on treifah and bore daughter—according to zeh v'zeh gorem daughter permitted though not concerned for seed; and likewise kilayim in kodashim invalid though not concerned for father's seed and no kilayim side—but we are not concerned nevertheless father's power and seed act in it and behold partial sheep; therefore Torah obligates gifts—for nevertheless father's power as behemah is in it and Torah rightly gave kohen power to take gifts; and he holds: since there is at least father's seed, whether concerned for father's seed and its power in it. And Rambam holds such a thing regarding oto v'et beno: we say sheep even partial sheep—and two explanations: if so rules Hebrew language and partial sheep called sheep; or such was tradition and unique transmission that "sheep" written means even partial sheep; and Rambam and they disputed and doubted as mentioned—not dividing or doubting Hebrew language rules; or they disputed tradition; and all the more per authors who say even though we say sheep even partial sheep, deer even partial deer we do not say—and if language nature indicates so, what difference sheep or deer; nevertheless such was tradition—and one may say in this yes but not in that. And therefore when tradition is fixed we doubt whether concerned for seed, etc.—according to those not concerned why tradition sheep even partial sheep—no such reality if he-goat on doe, no sheep even partial if not concerned; and if deer on she-goat behold entirely he-goat not partial sheep if not concerned for deer seed; and must say scriptural decree to obligate even though father he-goat and though not concerned for father's seed partial sheep exists and Torah obligates lashes—partial like whole as Tosafot hold in gifts; and from this born doubt whether we learn from oto v'et beno to similar matters such as kisuy, gifts, or where revealed; and some proof from needing to include koy milk—for otherwise all koy milk liable lashes; but we do not learn one from other and can reject; nevertheless doubt exists here. Challenge: mishnah Bekhorim chapter 2 lists several ways koy equals chayah and several ways behemah—and oto v'et beno prohibition not listed as equal to behemah; plainly: already taught in milk forbidden like behemah and likewise oto v'et beno—what this prohibition from that prohibition and tanna did not want to enumerate all prohibitions; and this if equal to milk; but per Rambam's elevation oto v'et beno has lashes and milk has no lashes—why not teach equal to behemah liable lashes in oto v'et beno like behemah and this not in milk where no lashes—why rely on milk; and therefore appears not like Rambam. However per Rambam regarding gifts priesthood: deer on he-goat liable half gifts and koy separate species tannaim did not decide—liable all gifts; and Ran wrote Rambam explains Rav Yochanan or to include gifts intending koy such separate species; and Yerushalmi Bekhorim decides us this matter on that case teaching liable foreleg etc. and R' Eliezer exempt—for Most High wrote Yerushalmi R' Eliezer exempt for now he doubted (exempt meaning not separate species only from deer-he-goat mixture and born doubt; and so beginning mishnah R' Eliezer says goat that mounted deer); and Rabbis say separate species and therefore liable—end, and these are Rambam's words: separate species Rabbis liable—for scriptural decree and plain. In any case we do not learn from that Bekhorot mishnah Rabbis only from koy separate species; and so we were taught there Chullin daf 80 after Rav Pappa's words R' Yehudah said koy separate species, etc.—see there Tosafot s.v. koy explaining R' Yochanan on mishnah dealing with koy such separate species—see there; and therefore resolved above challenge why mishnah did not teach liable lashes on oto v'et beno in behemah—for also in koy separate species mishnah deals and in such case no lashes for all; and impossible to teach; and resolved above challenge: and with this Rambam's words settled—sugya Chullin that page and especially Rav Pappa—he does not hold as thought mishnah deals koy separate species; only all from koy comes deer and he-goat as challenged from koy not slaughtered on Yom Tov; and if so challenged him if lashes in oto v'et beno should count in mishnah equal to behemah as stated; and nevertheless no lashes; and challenged tradition sheep even partial sheep why needed as stated; and nevertheless truly no tradition only they said sheep even partial sheep is good language; and likewise gifts and deer even partial deer in kisuy as stated; therefore Rav Pappa on his words: therefore, etc.; but after R' Yehudah in mishnah koy not slaughtered, etc.—deals separate species; and if so wonder why not teach for lashes as stated; and return to view tradition sheep even partial sheep tradition; and therefore proved lashes oto v'et beno in all forms: and kisuy and gifts doubt; therefore cover not on Yom Tov and weekday no blessing. And regarding gifts obligating half though doubtful—one may say Rambam holds like many authors: in double doubt extract from possessed hand as Tosafot first chapter Ketubot; and I elaborated this root in my book Klal HaTefissot on Sefer Takfo Kohen (and all the more priestly gifts where anyway Rambam Takfo Kohen does not extract—and therefore on half kohen has double doubt: one lest not concerned for father's seed and behold entirely sheep; and if you say concerned, lest we say sheep even partial sheep and he has half—therefore liable half gifts; and regarding kisuy though double doubt nevertheless from Torah prevent kisuy mitzvah; and so must say in Tosafot R' Eliezer's statement there doubts whether deer even partial deer—why R' Eliezer not exempt from kisuy though double doubt as stated; or to prevent mitzvah we do not say double doubt; and if so all Rambam's words correct: regarding oto v'et beno lashes; kisuy doubt; mishnah extract half from possessed; and examine well—for in my name witnesses I toiled greatly to settle Rambam and succeeded only in this manner.`,
});

// --- pitchei-teshuva (6) ---
patchFile('siman_016/pitchei-teshuva/part-001.txt', 'pitchei-teshuva', {
  '1#_': `<b>For the matter is doubtful.</b> See Knesset Yisrael s.k. 1 who wrote: after the matter is doubtful whether applies with males—permitted to slaughter the second at bein hashemashos from double doubt: perhaps it does not apply and perhaps tomorrow's day is the day; and he left requiring study; and see responsum Zikhron Yitzchak siman 101 who attacked him: for we hold in a matter that will be clarified we do not permit from double doubt; if so for oto v'et beno prohibition double doubt does not help to permit—for it will be clarified after dark—see there.`,
  '2#_': `<b>And there are those who forbid.</b> See responsum Zikhron Yitzchak siman 101 who wrote: if he slaughtered father and son in one day—permitted to eat on that day the one slaughtered last, since the matter is doubtful whether applies with males as above seif 2; if so double doubt: perhaps it does not apply and perhaps halachah follows those who say if he transgressed and slaughtered, permitted that day to eat them; and even though in matter that will be clarified double doubt does not help, nevertheless since prohibition is not for all the world only for the slaughterer himself, we do not judge it as matter that will be clarified, as Maharshal wrote Yevamot chapter HaAreil siman 34—see there; and in my humble opinion we do not rule like Maharshal—for we hold below siman 102 seif 4 in hagahah one who vows from a matter is called matter that will be clarified, and behold even now forbidden only to the vower and nevertheless called matter that will be clarified; and see on this responsum Noda Biyehudah Tinyana part Yoreh Deah siman 53 [and see Pri Megadim below siman 102 in Shaarei Teshuvah s.k. 2].`,
  '3#_': `<b>[Only through shechitah.</b> We read in Tosefta chapter 5 of Chullin: one who slaughters for healing, for non-Jew's eating, or for dogs' eating—forbidden because of oto v'et beno—perforce; and brought also in Peri Chadash s.k. 18; and it appears plain likewise if slaughtering non-Jew's animal there is oto v'et beno prohibition—for prohibition is on the slaughterer and it is written "you shall not slaughter" unconditionally; and we find similar regarding "do not muzzle" in Bava Metzia daf 90: Israelite who threshes non-Jew's threshing floor transgresses "do not muzzle"—see there; and Semag siman 138 s.k. 11 wrote: even the threshing belongs to non-Jew, etc.—see there; and because one teacher erred in this I needed to mention it.]`,
  '4#_': `<b>That they slaughter properly.</b> See Netziv what I wrote on intent of this hagahah.`,
  '5#_': `<b>They do not slaughter.</b> See responsum Zikhron Yitzchak siman 102 who wrote: if he sold the ben pakuah fetus that spread on ground to groom or bride on wedding day—need not inform not to slaughter that day, for explained above siman 13 if strange matter in it no shechitah required and automatically permitted to slaughter day mother slaughtered; and explained in Be'er HaGolah chapter Behemah HaMekishah wedding is strange matter—see there; and he left requiring study.`,
  '6#_': `<b>Pen them so they move.</b> It is hard for me—for oto v'et beno is matter that will be clarified and we do not say whatever is separated from majority, as Magen Avraham wrote siman 513 s.k. 13; and I found responsum Noda Biyehudah Tinyana part Yoreh Deah siman 8 in hagahah of Maharam Ben Chaviv who brought this challenge in name of his father in his book Tzelach on Beitzah 4:10—and he may his light shine wrote to settle per Orach Chaim siman 320 (and so below siman 102 seif 4 in hagahah): any prohibition not recognizable before it became mixed is nullified even though matter that will be clarified—one may say it deals where mother mixed before daughter's slaughter so prohibition not recognizable before mixture; and what Shulchan Aruch wrote "animal whose mother was slaughtered, etc., and became mixed"—intent: already mixed before slaughter—end; indeed I saw responsum Chatam Sofer siman 133 who wrote: in such case where mother mixed with others first and afterward slaughtered daughter—permitted afterward to slaughter from mixture without penning, for a thing that has permission is plainly not nullified except even importance of live animal does not help after mixture when no prohibition existed at mixture time; and he brought from Tosafot Temurah daf 30 end s.v. and the other: it appears sufficient in our case to separate one animal and slaughter all others—for since prohibition was not clear before mixture only after mixture prohibition arose, we rely on selection; and all the more if he slaughtered first one from mixture, permitted afterward to slaughter daughter; and see Chatam Sofer further he doubted essence of this law even if mixed after slaughtering daughter—and his view one in two nullifies and need not pen at all, even though live animal and matter that will be clarified—nevertheless Sages were stringent only in thing forbidden because of itself, unlike here where nothing happened to this animal only because mother or daughter slaughtered today—not stringent with live animal importance and matter that will be clarified; and Beit HaGadol goes by reasons that he holds to forbid eating last that day and therefore Beit HaGadol combined two laws reciprocally and Rosh brought them (chapter Oto V'et Beno siman 5)—unlike Rambam's view as sugya goes in chapter 25 daf 115 that in eating permitted—if so plain no place to say live animal importance and matter that will be clarified after no forbidden thing at all only Merciful One warned not to slaughter it; and if mother became mixed, nullified in majority and no prohibition name on mixed thing at all; and further since we exist, etc.—see there; and see further Noda Biyehudah there what he wrote to settle why here in oto v'et beno we rule pen them and in Orach Chaim siman 496 seif 2 ruled in case of two found three forbidden and did not write pen them, and wrote several answers [and see responsum Chasam Sofer seif 37 and examine].`,
});

// --- rabbi-akiva-eiger-yd (6) ---
patchFile('siman_016/rabbi-akiva-eiger-yd/part-001.txt', 'rabbi-akiva-eiger-yd', {
  '1#_': `(Siman 16 seif 4) <b>And if he slaughtered the first at bein hashemashos, etc., until night of sixth.</b> But at bein hashemashos of night of sixth he may not slaughter—for perhaps when he slaughtered the first at bein hashemashos it was then night and now still day; and truly it was hard for me why Tosafot conclude in Shabbat (daf 34b) all bein hashemashos are equal, only the doubt is perhaps all bein hashemashos is day or all night or part of first from day and part of second from night—if so if he slaughtered at bein hashemashos of night of fifth at beginning of bein hashemashos, he should be permitted to slaughter at bein hashemashos of tomorrow's day at its end—for if yesterday was night, all the more now at end of bein hashemashos which is night; and if now day, all the more yesterday at beginning of bein hashemashos was day; and I found in Ezrat Kohanim who was challenged on this by Turei Zahav and strained: truly only because of general stringency they forbade; and in sugya Shabbat where they say we cast it to stringency of two days—for what halachah—to tumah, why not state practical difference plainly for oto v'et beno: if doubt were only whether all from day or all from night, if slaughtered at bein hashemashos permitted to slaughter its offspring at bein hashemashos of morrow in any case, or both day or both night; but because we cast to stringency of two days lest part day part night—forbidden to slaughter offspring, lest when he slaughtered that one it was night and when slaughtering offspring it is day; and likewise practical difference in her vow at bein hashemashos husband cannot annul, lest at time of vow it was day and at annulment night and not "on the day he heard"; and even though immediately after vow he can annul since he could not annul before, it is like day he heard—nevertheless if he waited a bit he cannot annul afterward; and truly in responsum (siman 45) I wrote one may say he can annul from double doubt: perhaps when she vowed it was night; and if you say day, perhaps at annulment time it is day; and even though vows are matter that will be clarified and double doubt forbidden—nevertheless in husband's annulment which is against her will (he has no power that she release through sage and it is not called matter that will be clarified); however accordingly it is difficult here for oto v'et beno why not slaughter until night of sixth per Mechaber in Orach Chaim (siman 496) double doubt permitted even in matter that will be clarified; and see Shach (siman 110 s.k. 55)—if so he should be permitted to slaughter at bein hashemashos of night of sixth from double doubt: perhaps when he slaughtered mother it was day; and if you say night, perhaps also now when slaughtering offspring it is night—and requires study.`,
  '2#_': `(Seif 6) <b>And if he sold one to groom—the seller need not ask the buyer if buyer buys for groom; and if buyer buys for groom must inform the seller.</b> See Turei Zahav in his chiddushim to Keritut (daf 16a) s.v. mishnah at end of first chapter.`,
  '3#_': `(Shach s.k. 15) <b>Even partial sheep.</b> For we say regarding its son—all.`,
  '4#_': `(There s.k. 17) <b>Practical difference even for us.</b> In my humble opinion here the law does not apply—that there (siman 34) if the prohibition itself is not so severe that there are no lashes, he is not disqualified for testimony from Torah; but here the oto v'et beno prohibition is severe for there are lashes; and here it is doubt whether concerned for father's seed—he is disqualified from doubt; and like eating doubt of milk doubt of fat—it appears disqualified from doubt; for even though we do not lash from doubt, nevertheless it is like without forewarning he is disqualified, for the prohibition itself is severe; and so he will not be certainly disqualified—perhaps he did no prohibition at all.`,
  '5#_': `(Seif 10) <b>Permitted to slaughter the pregnant animal.</b> If mother found treifah—there is remedy for offspring if its months completed, permitted to slaughter it—plain forbidden to slaughter offspring that day for oto v'et beno; however even if offspring treifah, in my humble opinion one may argue permitted to slaughter offspring—for we hold shechitah that is not valid—its name is shechitah, meaning because shechitah helps purify from neveilah status, unlike here where even if fetus died it would not impart tumah as neveilah, for regarding this mother's shechitah helps, as stated explicitly Chullin (daf 75b); and if so slaughter of treifah fetus did not help at all, and one may say in such case it is not called shechitah.`,
  '6#_': `(Seif 12) <b>How is it remedied; and if first the mixture occurred and afterward he slaughtered the mother of one from the mixture.</b> One may say nullified in majority since prohibition was born in the mixture, even important thing and live animal nullified like matter that will be clarified below (siman 102)—so Chatam Sofer (siman 133); and ostensibly hidden from sugya Temurah (daf 30) "take out one for the dog and the rest all permitted"—why not challenge to permit all, for dog's portion nullifies prohibition in majority in the rest—for prohibition was born in mixture; and perhaps one may say: according to those who hold there is selection, it is as if possible to clarify the prohibition—for they can take one and say this is the prohibition; therefore no nullification rule; and with this resolved Tosafot's challenge there: according to Rabbenu Tam how does he challenge plainly, for we hold one in two—and per my words the challenge is in any-case reasoning: at minimum need forbid only one—for if one in two, all permitted by nullification; and if there is selection, take out one and rest permitted; and therefore the law should be that even per Chatam Sofer above, nevertheless must take one of them and set aside until tomorrow—for since we hold in rabbinic matters there is selection—and this is because we doubt whether law of selection exists or one in two, as Ran wrote chapter 3 of Gittin; and if so here perhaps there is selection and possible to clarify prohibition and not nullified at all, as I wrote; and when we come to this, one may say even without Chatam Sofer's reasoning and as implied from Rama's ruling who did not write so, only regarding matter that will be clarified (siman 102): one may say since never called prohibition name on it, no reason to say wait until eaten with prohibition; but regarding important thing in any case not nullified—nevertheless permission exists by taking one of them—for from Torah all permitted by nullification, only rabbinically forbidden for live animals not nullified and we rely on selection as we hold in rabbinic matters; and specifically when mother slaughtered and afterward became mixed—for there selection does not apply, as Tosafot Temurah wrote like any prohibition mixed in permission; but when prohibition born in mixture, permitted by taking one of them. And with this also resolved Tosafot Temurah's challenge: therefore he challenges "take out one"—according to view we hold in rabbinic matters there is selection; and since from Torah nullified, it is rabbinic; and resolved above challenge.`,
});

// --- nekudot-hakesef (2) ---
patchFile('siman_016/nekudot-hakesef/part-001.txt', 'nekudot-hakesef', {
  '1#_': `<b>(s.k. 11) Exempt implies but forbidden, etc.</b> This is not as proved in Talmud—for this exempt and permitted, as Rashba proved.`,
  '2#_': `<b>(s.k. 13) And further it appears plain when the animal, etc.</b> I omitted that Semag siman 167 states explicitly—I brought it in Shach s.k. 19; (s.k. 15) and so from what Rosh wrote, etc.—needlessly he brought from afar, for in Rashba's responsum source of this law it is explained explicitly; and also Rosh's words are no proof—for Rosh there refers to baraita dealing with Israelite who wanted to say we do not establish prohibition so long as seller did not inform—see there; also what he wrote "and it is plain if there is reason he does so to enhance his sale, his words are nothing"—see what I wrote in Siftei Kohen that Rosh's and Mordechai's and Hagahot Maimoniyot view: where in his possession he is believed even where one could say enhancing his sale he says so.`,
});

// --- kaf-hachayim (12) ---
patchFile('siman_016/kaf-hachayim/part-001.txt', 'kaf-hachayim', {
  '1#_': `<b>(1) [Seif 1] Forbidden to slaughter oto v'et beno in one day, etc.</b> Whether one person slaughters both or two who slaughtered one the mother and one the offspring, or the reverse—always lashes on slaughtering the last, from "or one day" "or one" handful "or one" (Vayikra 22).`,
  '2#_': `<b>(2) And if two slaughter at once, one the mother and one the offspring—even though there is room to doubt regarding lashes whether they receive lashes, nevertheless both transgressed the "or one day" there; handful there; Zivchei Tzedek "or one" Mani "or one."`,
  '3#_': `<b>(3) [Seif 2] For the matter is doubtful whether applies with males, etc.</b> For we doubt in Gemara (Chullin 78b) whether we hold like Chanania who holds concerned for father's seed, and we hold concerned stringently but not for lashes—for one does not receive lashes on doubt. Taz s.k. 2; Peri Chadash "or" 2.`,
  '4#_': `<b>(4) There. Whether permitted to slaughter father or offspring at bein hashemashos—for double doubt: perhaps we are not concerned for father's seed; and if you say concerned, lest yesterday or tomorrow is the day—and the matter requires study. Peleti "or" 1; but responsum Zikhron Yitzchak siman 101 attacked him: for we hold in matter that will be clarified we do not permit from double doubt; if so for oto v'et beno prohibition double doubt does not help—for it will be clarified after dark—see there. Pithei Teshuvah "or" 1; but b'dieved if already slaughtered at bein hashemashos—they are permitted even per view of those who forbid in seif 3; Zivchei Shamayim "or" 1; Zivchei Tzedek "or" 2.`,
  '5#_': `<b>(5) [Seif 3] And there are those who forbid on that day, etc.</b> And so agreed Perishah "or" 3; Semag "or" 3; Shofar "or" 3; Shulchan Gavoah end "or" 4; Machber "or" 5; handful "or" 6; Zivchei Ratzon siman 16 "or" 3; Zivchei Shamayim "or" 2; Zivchei Tzedek "or" 3.`,
  '6#_': `<b>(6) And even if slaughtered b'shogeg—forbidden.</b> Peri Chadash "or" 3; Kereti "or" 3; Semag there; Birkei Yosef "or" 4; handful there; Zivchei Brit there "or" 7; Zivchei Tzedek "or" 4; and this shogeg they are stringent about specifically one who says permitted; but shogeg who did not know it is oto v'et beno—penalty does not apply. Shenot Chaim "or" 3; Daat Torah "or" 4; Rabbenu Yerucham "or" 8; and see below "or" 11.`,
  '7#_': `<b>(7) And this is specifically for the slaughterer himself forbidden, but for others permitted.</b> Shach s.k. 3; Peri Chadash there; Lechem HaPanim "or" 4; Beit Lechem Yehudah "or" 1; Shofar "or" 3; Zivchei Brit there; place of Samuel in chiddushim of laws for Yoreh Deah this siman; however Semag there wrote to be stringent even for others; and so Erech HaShulchan there; handful there; Zivchei Rash there; Mani "or" 3; but Zivchei Tzedek "or" 5 wrote: since for unspecified Shulchan Aruch for him also permitted, we judge one may be stringent for him but for others permitted; however one who slaughters and sells to others should be stringent that they not benefit from his act, as Semag there; and so handful there; Mani there; and in hot places where if left until tomorrow it will spoil—it appears one may be lenient to sell that day.`,
  '8#_': `<b>(8) There hagahah. To eat the last.</b> But the first in any case permitted—for at slaughter no prohibition was created; and reason last forbidden—Ran wrote because of penalty, as in Orach Chaim siman 318 regarding Shabbat. Shach there; Peri Chadash there; Zivchei Brit there.`,
  '9#_': `<b>(9) And if father and son slaughtered in one day—responsum Zikhron Yitzchak siman 101 wrote permitted to eat on that day the one slaughtered last, since matter doubtful whether applies with males as above seif 2; if so double doubt: perhaps does not apply and perhaps halachah follows those who say if transgressed and slaughtered, permitted that day to eat them; and even though in matter that will be clarified double doubt does not help, nevertheless since prohibition not for all world only for slaughterer, we do not judge as matter that will be clarified as Maharshal wrote Yevamot chapter HaAreil siman 34—see there; however Pithei Teshuvah "or" 2 wrote on Zikhron Yitzchak's words: we do not rule like Maharshal—for we hold below siman 102 seif 4 in hagahah one who vows from matter is called matter that will be clarified, and behold even now forbidden only to vower and nevertheless called matter that will be clarified—end; and so Shofar below siman 102 "or" 2; Zivchei Tzedek "or" 6.`,
  '10#_': `<b>(10) And if two slaughtered together one mother and one daughter—both forbidden until evening, for both transgressed.</b> And if both belong to one person—one may be permitted to him. Semag "or" 3; Mani "or" 3.`,
  '11#_': `<b>(11) And specifically if they know they are oto v'et beno; but if they erred and forgot they are oto v'et beno, and all the more if they did not know at all until after slaughter—slaughter of both permitted even that day for themselves if pressed for meat.</b> Handful "or" 6; Tiferet Yehoshua "or" 5; Zivchei Tzedek "or" 8; and see above "or" 6.`,
  '12#_': `<b>(12) [Seif 4] The one day stated in oto v'et beno, etc.</b> This R' Shimon ben Zoma expounded: said in Bereishit "one day" and said in oto v'et beno "one day"—as the one day in Bereishit, the day follows the night, so the one day in oto v'et beno, the day follows the night; but in kodashim the night follows the day, as written "on the day of his offering he shall eat, he shall not leave of it until morning"—apparently the night after it is day of his offering until morning. Chullin chapter 3 81a.`,
});

// --- yad-avraham (3) ---
patchFile('siman_016/yad-avraham/part-001.txt', 'yad-avraham', {
  '1#_': `(Siman 16 seif 4) <b>And if he slaughtered the first at bein hashemashos of night of fifth, he may not slaughter the second until night of sixth.</b> For perhaps at bein hashemashos it is night and therefore forbidden to slaughter all of fifth day; and it appears this is with mother and offspring—for the whole seif deals with this since it mentions lashes; and with father and son there are no lashes as seif 2; but if father slaughtered at bein hashemashos of night of fifth, he may slaughter son that day—for double doubt: perhaps at bein hashemashos it is day and night does not follow day; and perhaps oto v'et beno does not apply at all with males, for we doubt whether applies with males or not as seif 2; and such double doubt helps even in matter that has permission, as Shach wrote siman 110 s.k. 55; and as I wrote double doubt s.k. 14; and measure of bein hashemashos see Orach Chaim siman 262 that it is like quarter hour before stars; and see what I wrote in chiddushim Shabbat (daf 34).`,
  '2#_': `(Seif 10) <b>And if the fetus went out alive after its mother's shechitah and spread on ground—they do not slaughter it in one day; and if he slaughtered he does not receive lashes.</b> Plain: if mother found treifah—for regarding fetus it is not shechitah and requires d'oraisa shechitah as siman 13 seif 3; and regarding oto v'et beno it is shechitah of treifah shechitah—for we hold like R' Meir in sugya chapter Kisuy HaDam (daf 86) as Bach and Acharonim s.k. 9; and if so if he slaughtered offspring that day—he receives lashes.`,
  '3#_': `(Seif 12) <b>Animal whose mother or daughter was slaughtered that day and became mixed and must slaughter from them that day—pen them, etc.</b> See siman 110 seif 6 in hagahah; and he was precise to say "and must slaughter" etc.—for otherwise forbidden, for it is matter that has permission tomorrow. <br><b>Shach</b> wrote the reason it is not nullified in majority: live animals are important and not nullified, as below siman 110; and he did not analyze that it is matter that will be clarified; and practical difference: if he transgressed and slaughtered them intentionally—forbidden for that person to eat that day as seif 3, and not nullified for him if this mixture mixed into a second mixture—for we hold siman 110 seif 8 in hagahah forbidden in matter that will be clarified; and if it were not matter that will be clarified, even though live animals not nullified and does not help if he slaughtered intentionally—for he is nullifying prohibition l'chatchila as siman 110 seif 2 and siman 99 and siman 101 seif 6; nevertheless nullified in sixty like other prohibitions—for what is permitted for others by nullifying prohibition as siman 99 seif 5 is not matter that will be clarified, since for him forbidden forever as s.k. 102; and even though I wrote it deals for need and without need permitted even in matter that will be clarified as proved there siman 110 seif 8 in hagahah—nevertheless specifically dry mixture in dry where there are two doubts: perhaps of permitted mixed into second mixture; and if you say of prohibition, perhaps what one eats is not prohibition; but when mixed in cooking, certainly no second doubt and forbids in majority; and further per R' Yehudah and Shulchan Aruch there only mixture of three permitted—see there and examine; and one may say Shach's words: he holds it deals where mixed before mother or daughter slaughtered so prohibition never recognizable—and such we hold not matter that will be clarified in Orach Chaim siman 320, as Noda Biyehudah Maarechet Chadash siman 8 per Magen Avraham Orach Chaim siman 513—but this is not agreed as Magen Avraham Laws of Me'ilah wrote, as I wrote above siman 15. <br><b>And know:</b> if he slaughtered the mixture b'shogeg—permitted even for him, for we do not penalize shogeg like intentional where he did not transgress d'oraisa—for from Torah one in two nullifies, as stated explicitly in sugya Gittin (daf 54) and Beit Yosef brought siman 99; and so Taz there siman 101 seif 6 and siman 110 seif 2: if slaughtered b'shogeg, nullified and we do not penalize shogeg like intentional unless he transgressed d'oraisa, such as not through mixture in seif 3 and Orach Chaim siman 318 regarding cooking on Shabbat b'shogeg forbidden that day—see there. <br><b>And I saw</b> responsum Chayei Adam siman 133 who wrote: per Rambam there is no prohibition when he transgressed and slaughtered, as Gemara Chullin (daf 109) "here there is no prohibition of nullification"—neither because of live animal importance nor matter that will be clarified; for it applies only in thing forbidden in eating or benefit, unlike here where impossible prohibition of slaughter l'chatchila.`,
});

// --- yad-ephraim (1) ---
patchFile('siman_016/yad-ephraim/part-001.txt', 'yad-ephraim', {
  '1#_': `<b>So they move from their established place.</b> Ba'er Hetev; and see Noda Biyehudah Maarechet Tinyana who wrote to answer what he challenged from Orach Chaim siman 496 in case of two years, etc.—why did he not rule pen them—see there.`,
});

